const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "<h3>Artículos</h3> <div class=\"articles-info items-intro-info\"> <span class=\"articles-info-icon\">i</span> <div>El article alemán no siempre coincide con el sistema de género inglés. Por lo tanto, es mejor aprender los sustantivos junto con el article.</div> </div> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>•</span>Ejemplos de artículos</h4> <div class=\"articles-grid\"> <div class=\"kurss-example\">der Tisch - table</div> <div class=\"kurss-example\">die Tür - la puerta</div> <div class=\"kurss-example\">das Messer - cuchillo</div> <div class=\"kurss-example\">das Mädchen - niña</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>♂</span>A menudo DER</h4> <p class=\"artikuli-explain\">DER suele ser personas masculinas, días, meses, estaciones y algunas palabras con determinadas terminaciones.</p> <h5 class=\"articles-subtitle\">Términos</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">-er → a menudo DER, por ejemplo: der Computer, der Lehrer <span class=\"artikuli-note\">pero no siempre</span></div> <div class=\"kurss-example\">-ling → a menudo DER, por ejemplo: der Schmetterling</div> <div class=\"kurss-example\">-ismus → a menudo DER, por ejemplo: der Tourismus, der Kapitalismus</div> <div class=\"kurss-example\">personas masculinas → der Mann, der Vater</div> <div class=\"kurss-example\">profesiones → der Lehrer, der Arzt</div> <div class=\"kurss-example\">marcas de automóviles → adecuado para BMW, adecuado para Mercedes</div> <div class=\"kurss-example\">días → der Montag, der Dienstag</div> <div class=\"kurss-example\">meses → der agosto, der diciembre</div> <div class=\"kurss-example\">Estaciones → der Sommer, der Winter</div> </div> <h5 class=\"articles-subtitle\">Ejemplos</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">der Mann - man</div> <div class=\"kurss-example\">der Vater - padre</div> <div class=\"kurss-example\">se adapta de lunes a lunes</div> <div class=\"kurss-example\">se adapta a agosto - agosto</div> <div class=\"kurss-example\">der Sommer - verano</div> <div class=\"kurss-example\">der Lehrer - profesor</div> <div class=\"kurss-example\">der Computer - computer</div> <div class=\"kurss-example\">der Schmetterling - mariposa</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>♀</span>A menudo DIE</h4> <p class=\"artikuli-explain\">DIE es a menudo una persona femenina, plural y palabras que terminan en -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p> <h5 class=\"articles-subtitle\">Términos</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div> <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div> <div class=\"kurss-example\">-keit → die Möglichkeit</div> <div class=\"course-example\">-schaft → die Mannschaft</div> <div class=\"course-example\">-ion → die Nation</div> <div class=\"course-example\">-tät → die Universität</div> <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div> <div class=\"kurss-example\">personas femeninas → die Frau, die Mutter</div> <div class=\"kurss-example\">marcas de motocicletas → la Harley-Davidson, la Yamaha</div> <div class=\"kurss-example\">plural → los automóviles, la casa</div> <div class=\"kurss-example\">plural casi siempre → die Autos, die Häuser, die Kinder</div> </div> <h5 class=\"articles-subtitle\">Ejemplos</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">die Frau - mujer</div> <div class=\"kurss-example\">die Mutter - madre</div> <div class=\"kurss-example\">die Wohnung - apartamento</div> <div class=\"kurss-example\">die Rechnung - factura</div> <div class=\"kurss-example\">die Freiheit - libertad</div> <div class=\"kurss-example\">die Möglichkeit - oportunidad</div> <div class=\"kurss-example\">die Mannschaft - el equipo</div> <div class=\"kurss-example\">die Nation - nación</div> <div class=\"kurss-example\">die Universität - la universidad</div> <div class=\"kurss-example\">die Polizei - la policía</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>◇</span>A menudo DAS</h4> <p class=\"artikuli-explain\">DAS suelen tener diminutivos con -chen / -lein, muchas palabras con -ment / -um y verbos como sustantivos.</p> <h5 class=\"articles-subtitle\">Términos</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div> <div class=\"kurss-example\">-lein → das Fräulein</div> <div class=\"kurss-example\">-ment → das Instrument</div> <div class=\"kurss-example\">-um → das Zentrum, das Museum</div> <div class=\"kurss-example\">metales → das Gold, das Silber, das Eisen</div> <div class=\"kurss-example\">elementos químicos → das Eisen, das Sauerstoff</div> <div class=\"kurss-example\">hoteles → das Hotel</div> <div class=\"kurss-example\">colores como sustantivos → das Rot, das Blau</div> <div class=\"kurss-example\">verbo como sustantivo → das Essen, das Lernen</div> <div class=\"kurss-example\">verbos como sustantivos → das Essen, das Lernen, das Lesen</div> </div> <h5 class=\"articles-subtitle\">Ejemplos</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">das Kind - niño</div> <div class=\"kurss-example\">das Mädchen - niña</div> <div class=\"kurss-example\">das Häuschen - la cabaña</div> <div class=\"kurss-example\">das Instrument - instrumento</div> <div class=\"kurss-example\">das Zentrum - centro</div> <div class=\"kurss-example\">das Museum - museo</div> <div class=\"kurss-example\">das Essen - comer / comida</div> <div class=\"course-example\">das Lernen - Aprender</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"artikuli-header\"><span>!</span>Excepciones importantes / debe aprender con el article</h4> <p class=\"artikuli-explain\">Para algunas palabras, el article no se puede determinar de manera confiable por la terminación o el origen letón. Es mejor estudiarlos junto con el article.</p> <div class=\"articles-grid\"> <div class=\"kurss-example\">die Tür - la puerta</div> <div class=\"kurss-example\">das Messer - el cuchillo</div> <div class=\"kurss-example\">die Sonne - el sol</div> <div class=\"kurss-example\">der Mond - la luna</div> <div class=\"kurss-example\">das Mädchen - niña</div> <div class=\"kurss-example\">das Auto - coche</div> <div class=\"kurss-example\">der Käse - queso</div> <div class=\"kurss-example\">die Gabel - fork</div> </div> </section> <div class=\"articles-info items-bottom-info\"> <span class=\"articles-info-icon\">i</span> <div>Ayuda para terminaciones y grupos de palabras adivinar el article, pero no son una regla 100% segura. Si no está seguro, aprenda la palabra junto con el article.</div> </div>",
  "kurssPronounsLesson": "\n  <h3>Pronombres</h3> <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativo, Akkusativo y Dativo - formas de pronombres.</div>\n  </div> \n  \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativo - ¿qué?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich - I</div><div class=\"kurss-example\">du - tú</div><div class=\"kurss-example\">er - él</div><div class=\"kurss-example\">sie - ella</div><div class=\"kurss-example\">yo - eso</div><div class=\"kurss-example\">wir - nosotros</div><div class=\"kurss-example\">ihr - tú</div><div class=\"kurss-example\">atan - ellos / ella</div><div class=\"kurss-example\">atan - tú (cortesía)</div></div>\n  </section> \n  \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Acusativo - ¿qué?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich - yo</div><div class=\"kurss-example\">dich - tú</div><div class=\"kurss-example\">ihn - su (v.)</div><div class=\"kurss-example\">sie - su (s.)</div><div class=\"kurss-example\">yo - eso</div><div class=\"kurss-example\">él - nosotros</div><div class=\"kurss-example\">euch - tú</div><div class=\"kurss-example\">sie - ellos/ella</div><div class=\"kurss-example\">sie - tú (cortesía)</div></div>\n  </section> \n  \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativo - ¿a quién?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir - yo</div><div class=\"kurss-example\">dir - tú</div><div class=\"kurss-example\">ihm - él / eso</div><div class=\"kurss-example\">ihr - ella</div><div class=\"kurss-example\">uns - nosotros</div><div class=\"kurss-example\">euch - tú</div><div class=\"kurss-example\">ihnen - ellos / para ellos</div><div class=\"kurss-example\">Ihnen - para ti (cortesía)</div></div>\n  </section> \n  \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>¿Cómo elegir una forma?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativo</span> - sujeto de la oración (¿quién lo hace?)</li><li><span class=\"case-red\">Akkusativ</span> - objeto directo (¿qué?)</li><li><span class=\"case-green\">Dativo</span> - objeto indirecto (¿a quién?)</li></ul>\n  </section> \n  \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Ejemplos</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Te veo.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. - Veo él.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Nos gustas.</div><div class=\"kurss-example\">Ich helpe <span class=\"case-green\">dir</span>. — Te estoy ayudando.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Le doy el libro.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Te lo agradecemos.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>El Nominativo es siempre el sujeto de la oración, mientras que Akkusativ y Dativ son los objetos. Mire el verbo y pregunte: <span class=\"case-red\">¿qué?</span> o <span class=\"case-green\">¿quién?</span></div>\n  </div>",
  "kurssPronunciationLesson": "<h3>Vocales: largas y cortas</h3> <p class=\"kurss-lesson-intro\">En alemán, las vocales pueden ser largas o cortas. Esto afecta la pronunciación de la palabra.</p> <section class=\"course-lesson-section\"> <h4>Vocal larga</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">cálida (varm) - cálida</div><div class=\"kurss-example\">tripa (get) - buena</div><div class=\"kurss-example\">Tat (tat) - trabajo / acción</div><div class=\"kurss-example\">Flur (flūr) - pasillo</div><div class=\"kurss-example\">Weg (vēk) - camino</div><div class=\"kurss-example\">Cabaña (hūt) - sombrero</div><div class=\"kurss-example\">Hof (hōf) - patio</div><div class=\"kurss-example\">Schlaf — dormir</div></div> <p>Si una vocal va seguida de una consonante, la la vocal a menudo se pronuncia larga.</p> </section> <section class=\"course-lesson-section\"> <h4>Vocal corta</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilc) - hongo</div><div class=\"kurss-example\">Wort (vort) - palabra</div><div class=\"kurss-example\">Mund (munt) - boca</div><div class=\"kurss-example\">calvo (balt) - pronto</div><div class=\"kurss-example\">scharf (bufanda) - culo</div><div class=\"kurss-example\">Feld (fieltro) - campo</div><div class=\"kurss-example\">voll (fol) - completo</div></div> <p>Si una vocal va seguida de dos o más consonantes, la vocal suele pronunciarse corta.</p> </section> <section class=\"course-lesson-section\"> <h4>Terminales en / el / er</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) - sing</div><div class=\"kurss-example\">tragen (trāgen) - llevar</div><div class=\"kurss-example\">Garten (garten) - jardín</div><div class=\"kurss-example\">Vogel (fogel) - pájaro</div><div class=\"kurss-example\">Segel (zēgel) - vela</div><div class=\"kurss-example\">Braten (brāten) - asado</div><div class=\"kurss-example\">Bogen (bōgen) - arco</div><div class=\"kurss-example\">Spiegel - espejo</div><div class=\"kurss-example\">Dedo (dedo) - dedo</div><div class=\"kurss-example\">Cabestro (cabrestante) - soporte</div><div class=\"kurss-example\">Arbeiter (arbaiter) - trabajador</div><div class=\"kurss-example\">Häuser (hoizer) - inicio</div><div class=\"kurss-example\">wieder (wieder) - otra vez</div><div class=\"kurss-example\">breiter (más brillante) - más ancho</div></div> </section> <section class=\"course-lesson-section\"> <h4>Letra h como longitud</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rämen) - marco</div><div class=\"kurss-example\">Ohr (ōr) - oreja</div><div class=\"kurss-example\">Kohle (kōle) - carbón</div><div class=\"kurss-example\">Zahl (căl) - número</div><div class=\"kurss-example\">ihn (īn) - su</div><div class=\"kurss-example\">ihm (īm) - para él</div><div class=\"kurss-example\">Huhn (hūn) - pollo</div><div class=\"kurss-example\">nahm (nām) - tomó</div><div class=\"kurss-example\">nehmen (nēmen) - tomar</div><div class=\"kurss-example\">Schuh (shuh) - zapato</div></div> <p>En algunas palabras, h alarga la vocal anterior. En tales casos, la h normalmente no se pronuncia.</p> </section> <section class=\"course-lesson-section\"> <h4>Termina con e</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) - lámpara</div><div class=\"kurss-example\">Hase (neblina) - liebre</div><div class=\"kurss-example\">Knabe (pico) - niño</div><div class=\"kurss-example\">Rabe (rabe) - cuervo</div></div> </section> <section class=\"course-lesson-section\"> <h4>Long i = ie</h4> <div class=\"kurss-example\"><div class=\"kurss-example\">die (dī) - el article \"die\"</div><div class=\"kurss-example\">diese (dīze) - esto / estos</div><div class=\"kurss-example\">wieder (wieder) - otra vez</div><div class=\"kurss-example\">Fliege (fliege) - mosca</div><div class=\"kurss-example\">Ziege (cīge) - cabra</div><div class=\"kurss-example\">Stiel (štīl) - tallo</div><div class=\"kurss-example\">Dieb (dīp) - ladrón</div><div class=\"kurss-example\">hier (hīr) - aquí</div></div> <p>La i larga en alemán suele escribirse como ie.</p> </section> <section class=\"course-lesson-section\"> <h4>Vocales dobles</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (hierba) - hierba</div><div class=\"kurss-example\">Saat (zāt) - sembrar</div><div class=\"kurss-example\">Staat (estado) - país</div><div class=\"kurss-example\">Beere (funeral) - baya</div><div class=\"kurss-example\">Ver (ver) - lago / mar</div><div class=\"kurss-example\">Remolacha (bēt) - cama</div><div class=\"kurss-example\">Bota (bōt) - barco</div><div class=\"kurss-example\">Moor (mōr) - pantano</div><div class=\"kurss-example\">Moos (mōs) - musgo</div></div> <p>Vocales dobles normalmente se pronuncian largos.</p> </section> <section class=\"course-lesson-section\"> <h4>ä</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) - pared</div><div class=\"kurss-example\">Wände (vende) - paredes</div><div class=\"kurss-example\">Vater (fäter) - padre</div><div class=\"kurss-example\">Väter (fēter) - padres</div><div class=\"kurss-example\">Schrank (šrank) - armario</div><div class=\"kurss-example\">Schränke (shrenke) - armarios</div><div class=\"kurss-example\">Banco (banco) - banco / banco</div><div class=\"kurss-example\">Bänke (benke) - escalones</div><div class=\"kurss-example\">Tal (lejos) - valle</div><div class=\"kurss-example\">Täler (tēler) - valles</div></div> <p>ä es una afinación de a.</p> </section> <section class=\"course-lesson-section\"> <h4>ö</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Rosa (rōze) - rosa</div><div class=\"kurss-example\">Röschen (rēschen) - roseta</div><div class=\"kurss-example\">Ofen (ōfen) - horno</div><div class=\"kurss-example\">Öfen (öfen) - horno</div><div class=\"kurss-example\">Rock (rok) - falda</div><div class=\"kurss-example\">Röcke (röke) - falda</div></div> <p>ö es un transposición de o.</p> </section> <section class=\"course-lesson-section\"> <h4>ü</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurs) - corto</div><div class=\"kurss-example\">kürzer (kurser) - más corto</div><div class=\"kurss-example\">Kunst (kunst) - arte</div><div class=\"kurss-example\">Künste (künste) - arte</div><div class=\"kurss-example\">Mutter (muter) - madre</div><div class=\"kurss-example\">Mütter (mutter) - madres</div></div> <p>ü es un transposición de u.</p> </section> <section class=\"course-lesson-section\"> <h4>Sonidos de inmersión: äu</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) - árbol</div><div class=\"kurss-example\">Bäume (boime) - árboles</div><div class=\"kurss-example\">Haus (haus) - casa</div><div class=\"kurss-example\">Häuser (hoizer) - casas</div><div class=\"kurss-example\">Strauch (štrauh) - arbusto</div><div class=\"kurss-example\">Sträucher (štroiher) - arbustos</div><div class=\"kurss-example\">Maus (maus) - ratón</div><div class=\"kurss-example\">Mäuse (moise) - ratones</div></div> </section> <section class=\"course-lesson-section\"> <h4>Dip: eu</h4> <div class=\"kurss-example\"><div class=\"kurss-example\">heute (hoite) - hoy</div><div class=\"kurss-example\">Leute (loite) - gente</div><div class=\"kurss-example\">neu (noi) - nuevo</div><div class=\"kurss-example\">neun (noin) - nueve</div></div> </section> <section class=\"course-lesson-section\"> <h4>Diplomática: ei</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (principal) - mío</div><div class=\"kurss-example\">dein (dain) - tuyo</div><div class=\"kurss-example\">sein (zain) - ella / ella / be</div><div class=\"kurss-example\">frei (frai) - gratis</div><div class=\"kurss-example\">arbeiten (arbaiten) - trabajar</div></div> </section> <section class=\"course-lesson-section\"> <h4>2. notas de pronunciación de conferencias</h4> <ul class=\"kurss-summary-list\"><li>en las palabras ich, nicht, rechnen, zeichnen \"ch\" se pronuncia suave</li><li>en las palabras arbeiten y zeichnen \"ei\" se pronuncia como \"ai\"</li><li>\"sp\" al principio de la palabra se pronuncia como \"šp\"</li><li>en el verbo tun la letra \"u\" se pronuncia larga</li></ul> </section> <section class=\"course-lesson-section\"> <h4>Resumen</h4> <ul class=\"kurss-summary-list\"><li>una consonante después de una vocal → a menudo una vocal larga</li><li>dos o más consonantes → a menudo una vocal corta</li><li>h puede alargar una vocal</li><li>es decir, a menudo significa larga i</li><li>las vocales dobles suelen ser largo</li></ul></sección>",
  "kurssConsonantsLesson": "<h3>Consonantes y combinaciones de letras</h3> <p class=\"kurss-lesson-intro\">En alemán, algunas consonantes y combinaciones de letras se pronuncian de forma diferente a cómo se escriben. Esta conferencia contiene los ejemplos más importantes para principiantes.</p> <section class=\"course-lesson-section\"> <h4>Consonantes</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) - rueda</div><div class=\"kurss-example\">die Räder (rēder) - ruedas</div><div class=\"kurss-example\">Bad (bāt) - baño</div><div class=\"kurss-example\">Bäder (bäder) - baños</div></div> <p>Las consonantes al final de una palabra a menudo no se pronuncian como están escritas.</p> </section> <section class=\"course-lesson-section\"> <h4>ch</h4> <p>“ch” se puede pronunciar suave o duro. En algunas palabras suena como \"h\", en otras más parecido a \"k\".</p> <div class=\"course-examples\"><div class=\"course-example\">rechnen (rehnen) - calcular</div><div class=\"course-example\">zeichnen (caihnen) - dibujar</div><div class=\"course-example\">nicht (niht) - not</div><div class=\"course-example\">schlecht (šleht) - malo</div><div class=\"course-example\">mich (mih) - yo</div><div class=\"course-example\">dich (dih) - tú</div><div class=\"kurss-example\">Strauch (štrauh) - arbusto</div><div class=\"kurss-example\">noch (noh) - quiet</div><div class=\"kurss-example\">Nacht (naht) - noche</div></div> </section> <section class=\"course-lesson-section\"> <h4>sch</h4> <p>“sch” en alemán se pronuncia como “š” letón.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule - escuela</div><div class=\"kurss-example\">Schüler - estudiante</div><div class=\"kurss-example\">Schiff - barco</div><div class=\"kurss-example\">Schraube - tornillo</div></div> </section> <section class=\"course-lesson-section\"> <h4>sp y st al comienzo de la palabra</h4> <p>Al principio de una palabra o sílaba, \"sp\" a menudo se pronuncia como \"šp\" y \"st\" como \"št\".</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (špīlen) - jugar</div><div class=\"kurss-example\">Sprung (šprung) - saltar</div><div class=\"kurss-example\">stehen (štēen) - estar de pie</div><div class=\"kurss-example\">puesto (štal) - granero</div><div class=\"kurss-example\">Stand (štant) - posición / lugar</div></div> </section> <section class=\"course-lesson-section\"> <h4>qu</h4> <p>“qu” generalmente se pronuncia como “kv” en alemán.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual ​​(kvāl) - tortura</div><div class=\"kurss-example\">Quartier (kvartīr) - barrio / alojamiento</div><div class=\"kurss-example\">quer (kvær) - a través</div></div> </section> <section class=\"course-lesson-section\"> <h4>s y z</h4> <p>La 's' al principio de una palabra a menudo suena como una 'z'. La letra \"z\" en alemán suena como la \"c\" letona.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zāgen) - decir</div><div class=\"kurss-example\">singen (zingen) - cantar</div><div class=\"kurss-example\">Rose (rōze) - rose</div><div class=\"kurss-example\">Zahl (pollo) - número</div><div class=\"kurss-example\">Zeit (cait) - tiempo</div><div class=\"kurss-example\">Zink (zinc) - zinc</div></div> </section> <section class=\"course-lesson-section\"> <h4>v</h4> <p>En alemán, 'v' a menudo se pronuncia como 'f'. En palabras extranjeras, a menudo suena como la \"v\" letona.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fäter) - padre</div><div class=\"kurss-example\">von (fon) - no</div><div class=\"kurss-example\">viel (fīl) - many</div><div class=\"kurss-example\">vier (fīr) - cuatro</div><div class=\"kurss-example\">Villa (villa) - villa</div><div class=\"kurss-example\">Klavier (piano) - piano</div></div> </section> <section class=\"course-lesson-section\"> <h4>x e y</h4> <p>'x' se pronuncia como 'ks'. \"y\" se pronuncia como \"ü\" en algunas palabras.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (feliks) - Felix</div><div class=\"kurss-example\">Axt (akst) - hacha</div><div class=\"kurss-example\">Mystik (mustik) - misticismo</div><div class=\"kurss-example\">Nyx (nūks) - Nikse</div><div class=\"kurss-example\">Mythe (boca) - mito</div></div> </section> <section class=\"course-lesson-section\"> <h4>ß</h4> <p>“ß” se pronuncia “s” en alemán.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (füs) - pie</div><div class=\"kurss-example\">Füße (füse) - pies</div><div class=\"kurss-example\">Grüße (grüße) - saludos</div></div> </section> <section class=\"course-lesson-section\"> <h4>Resumen</h4> <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st al principio → šp / št</li><li>qu → kv</li><li>z → c</li><li>v a menudo → f</li><li>x → ks</li><li>ß → s</li></ul> </section>",
  "kurssVerbBasicsLesson": "<h3>Conceptos básicos de los verbos</h3> <p class=\"kurss-lesson-intro\">1. verbos y conjugaciones de la conferencia.</p> <section class=\"course-lesson-section\"> <h4>Verbos</h4> <div class=\"course-examples\"><div class=\"course-example\">kommen - venir</div><div class=\"course-example\">gehen - ir</div><div class=\"course-example\">stehen - estar de pie</div><div class=\"course-example\">singen - to cantar</div></div> </section> <section class=\"curso-lección-sección\"> <h4>kommen</h4> <div class=\"course-example\"><div class=\"course-example\">ich komme - yo vengo</div><div class=\"course-example\">du kommst - tú vienes</div><div class=\"course-example\">er kommt - él viene</div><div class=\"course-example\">sie kommt - ella viene</div><div class=\"course-example\">wir kommen - nosotros venimos</div><div class=\"course-example\">ihr kommt - tú vienes</div><div class=\"kurss-example\">sie kommen - ellos / ellos vienen</div></div> </section> <section class=\"course-lesson-section\"> <h4>gehen</h4> <div class=\"course-example\"><div class=\"course-example\">ich gehe - yo voy</div><div class=\"course-example\">du gehst - tú vas</div><div class=\"course-example\">er geht - él va</div><div class=\"course-example\">sie geht - ella va</div><div class=\"course-example\">wir gehen - nosotros vamos</div><div class=\"course-example\">ihr geht - tú vas</div><div class=\"kurss-example\">sie gehen - ellos / ella va</div></div> </section> <section class=\"course-lesson-section\"> <h4>stehen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich stehe - yo estoy de pie</div><div class=\"course-example\">du stehst - tú estás de pie</div><div class=\"course-example\">er steht - él está de pie</div><div class=\"course-example\">sie steht - ella está de pie</div><div class=\"course-example\">wir stehen - nosotros estamos de pie</div><div class=\"course-example\">ihr steht - tú estás de pie</div><div class=\"kurss-example\">sie stehen - ellos / ella se para</div></div> </section> <section class=\"course-lesson-section\"> <h4>canta</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe - yo canto</div><div class=\"kurss-example\">du singst - tú cantas</div><div class=\"kurss-example\">er singt - él canta</div><div class=\"kurss-example\">sie singt - ella canta</div><div class=\"kurss-example\">wir singen - nosotros cantamos</div><div class=\"kurss-example\">ihr singt - tú cantas</div><div class=\"kurss-example\">sie singen - ellos / ellos cantan</div></div> </section> <section class=\"course-lesson-section\"> <h4>2. verbos de conferencia</h4> <div class=\"course-example\"><div class=\"course-example\">spielen - jugar</div><div class=\"course-example\">arbeiten - trabajar</div><div class=\"course-example\">fragen - preguntar</div><div class=\"course-example\">antworten - responder</div><div class=\"course-example\">rechnen - calcular</div><div class=\"course-example\">zeichnen - dibujar</div><div class=\"course-example\">tun - hacer</div></div> </section> <section class=\"course-lesson-section\"> <h4>jugar</h4> <div class=\"course-examples\"><div class=\"course-example\">ich spielt - Yo juego</div><div class=\"course-example\">du spielst - tú juegas</div><div class=\"course-example\">er spielt - él juega</div><div class=\"course-example\">sie spielt - ella juega</div><div class=\"course-example\">wir spielen - nosotros jugamos</div><div class=\"course-example\">ihr spielt - tú juegas</div><div class=\"kurss-example\">sie spielen - ellos / ella en el juego</div></div> </section> <section class=\"course-lesson-section\"> <h4>arbeiten</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite - yo trabajo</div><div class=\"kurss-example\">du arbetest - tú trabajas</div><div class=\"kurss-example\">er arbeitt - él trabaja</div><div class=\"kurss-example\">sie arbeitt - ella trabaja</div><div class=\"kurss-example\">wir arbeiten - nosotros trabajamos</div><div class=\"kurss-example\">ihr arbeitt - tú trabajas</div><div class=\"kurss-example\">sie arbeiten - ellos / ella trabajan</div></div> </section> <section class=\"course-lesson-section\"> <h4>fragen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich frage - te pregunto</div><div class=\"course-example\">du fragst - tú pregunta</div><div class=\"course-example\">er fragt - él pregunta</div><div class=\"course-example\">sie fragt - ella pregunta</div><div class=\"course-example\">wir fragen - nosotros preguntamos</div><div class=\"course-example\">ihr fragt - tú preguntas</div><div class=\"kurss-example\">sie fragen - ellos / ellos preguntan</div></div> </section> <section class=\"course-lesson-section\"> <h4>respuesta</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte - Yo respondo</div><div class=\"kurss-example\">du antwortet - tú respondes</div><div class=\"kurss-example\">er antwortet - él responde</div><div class=\"kurss-example\">sie antwortet - ella responde</div><div class=\"kurss-example\">wir antworten - nosotros respondemos</div><div class=\"kurss-example\">ihr antwortet — tú respondes</div><div class=\"kurss-example\">sie antworten — ellos/ellos responden</div></div> </section> <section class=\"course-lesson-section\"> <h4>rechnen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich rechne - yo calculo</div><div class=\"course-example\">du rechnest - tú calcula</div><div class=\"course-example\">er rechnet - él calcula</div><div class=\"course-example\">sie rechnet - su cálculo</div><div class=\"course-example\">wir rechnen - nosotros calculamos</div><div class=\"kurss-example\">ihr rechnet - tú calcula</div><div class=\"kurss-example\">sie rechnen - ellos / ella factura</div></div> </section> <section class=\"course-lesson-section\"> <h4>zeichnen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich zeichne - yo dibujo</div><div class=\"course-example\">du zeichnest - tú dibujas</div><div class=\"course-example\">er zeichnet - él dibuja</div><div class=\"course-example\">sie zeichnet - ella dibuja</div><div class=\"course-example\">wir zeichnen - nosotros dibujamos</div><div class=\"course-example\">ihr zeichnet - tú tú dibuja</div><div class=\"kurss-example\">sie zeichnen - ellos / ella dibuja</div></div> </section> <section class=\"course-lesson-section\"> <h4>allí</h4> <div class=\"course-examples\"><div class=\"course-example\">ich tue - yo hago</div><div class=\"course-example\">du tust - tú haces</div><div class=\"course-example\">er tut - él lo hace</div><div class=\"course-example\">sie tut - ella lo hace</div><div class=\"course-example\">wir tun - nosotros lo hacemos</div><div class=\"course-example\">ihr tut - tú lo haces</div><div class=\"kurss-example\">sie tun - ellos / ellos lo hacen</div></div> </section>",
  "kurssSentenceStructureLesson": "<h3>Estructura de la oración</h3> <p class=\"kurss-lesson-intro\">En una oración interrogativa, el verbo suele aparecer primero en alemán.</p> <section class=\"course-lesson-section\"> <h4>Ejemplos</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. - Ya vienes.</div><div class=\"kurss-example\">Kommst du? — ¿Vienes?</div><div class=\"kurss-example\">Er singt. — Él canta.</div><div class=\"kurss-example\">Singt er? — ¿Canta?</div><div class=\"kurss-example\">Stehst du? — ¿Estás de pie?</div><div class=\"kurss-example\">Si, ich stehe. — Sí, estoy de pie.</div><div class=\"kurss-example\">Geht ihr? — ¿Vas a ir?</div><div class=\"kurss-example\">Ja, wir gehen. — Sí, vamos.</div></div> </section> <section class=\"course-lesson-section\"> <h4>Preguntas con “was”</h4> <p>Si una pregunta comienza con una palabra interrogativa, el verbo en alemán suele ir inmediatamente después de la palabra interrogativa.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">¿Fue tust du? - ¿Qué estás haciendo?</div><div class=\"kurss-example\">¿Estaba tut er? — ¿Qué está haciendo?</div><div class=\"kurss-example\">¿Era tut sie? — ¿Qué está haciendo?</div><div class=\"kurss-example\">¿Estaba tun sie? — ¿Qué están haciendo?</div></div> </section> <section class=\"course-lesson-section\"> <h4>Negación con “nicht”</h4> <p>Cuando la negación \"nicht\" se refiere a un verbo, normalmente va después del verbo en alemán.</p> <div class=\"course-examples\"><div class=\"course-example\">Ich spiele nicht. — No juego.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul no pregunta.</div><div class=\"kurss-example\">Er kommt nicht. — No viene.</div><div class=\"kurss-example\">Sie singen nicht. — Ellos/ellos no cantan.</div></div> </section> <section class=\"course-lesson-section\"> <h4>Oraciones de la lección 2</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">¿Juegas? - ¿Juegas?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — No, no juego, trabajo.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitt. — Paul no pregunta, trabaja.</div><div class=\"kurss-example\">Arbeitest du? - ¿Trabajas?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — No, no estoy trabajando, estoy cantando.</div><div class=\"kurss-example\">¿Fue Pablo? — ¿Qué está haciendo Paul?</div><div class=\"kurss-example\">Er spielt. — Está jugando.</div><div class=\"kurss-example\">¿Era tut Marie? — ¿Qué está haciendo María?</div><div class=\"kurss-example\">Sie singt. — Ella canta.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul toca, pero María canta.</div><div class=\"kurss-example\">Singt ihr? — ¿Cantas?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — No, no cantamos, trabajamos.</div><div class=\"kurss-example\">¿Eran tun Paul und Marie? - ¿Qué están haciendo Paul y María?</div><div class=\"kurss-example\">Sie fragen. — Preguntan.</div><div class=\"kurss-example\">Sie antworten nicht. — No contestan.</div><div class=\"kurss-example\">Wer arbeitt? — ¿Quién trabaja?</div><div class=\"kurss-example\">Wir arbeiten. — Trabajamos.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. - Nosotros contar y dibujar.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Vienen, preguntan, responden, trabajan, juegan, cantan y se van.</div></div> </section>",
  "kurssLesson2": "<h3>Lección 2</h3> <p class=\"kurss-lesson-intro\">Segunda lección: diálogos, palabras, pronunciación, gramática y traducción.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div> <div class=\"kurss-example\">Paul fragt nicht, er arbeitt.</div> <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div> <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div> <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div> <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div> <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div> <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div> <div class=\"kurss-example\">Wer arbeitt?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div> <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div> </div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number\" lesson1-número-verde\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">spielen - jugar; jugar</div> <div class=\"course-example\">nein - no</div> <div class=\"course-example\">nicht - no</div> <div class=\"kurss-example\">arbeiten - trabajar</div> <div class=\"kurss-example\">fragen - preguntar</div> <div class=\"kurss-example\">was tut er? ¿Qué está haciendo?</div> <div class=\"kurss-example\">¿Estaba tun sie? — ¿qué hacen ellos?</div> <div class=\"curso-example\">aber - pero</div> <div class=\"kurss-example\">antworten - responder</div> <div class=\"kurss-example\">rechnen - calcular</div> <div class=\"kurss-example\">zeichnen - dibujar</div> <div class=\"kurss-example\">Marie</div> </div> </div> </details> <details class=\"lesson1-acordeón\"> <summary><span class=\"lesson1-number\" lesson1-número-púrpura\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En las palabras ich, nicht, rechnen, zeichnen, el sonido ch se pronuncia suavemente, aproximadamente como en las palabras letonas: technika, Frīdrihs.</div><div class=\"kurss-example\">En las palabras arbeiten, zeichnen, el diptongo ei se pronuncia aproximadamente como el sonido e bemol letón seguido de i.</div><div class=\"kurss-example\">El grupo de consonantes sp se pronuncia como šp: spielen (špīlen).</div><div class=\"kurss-example\">En el verbo tun u se pronuncia largo en todas las personas.</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-número-azul\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>1</span>Terminaciones con e</h4> <div class=\"lesson1-grammar-note\">Si la raíz del verbo termina en t, d, chn, entonces las terminaciones -st y -t están precedidas por e.</div> <h5 class=\"lesson2-subtitle\">arbeiten</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">ich arbeite</div><div class=\"course-example\">du arbeite</div><div class=\"course-example\">er Arbeit</div><div class=\"course-example\">sie arbeit</div><div class=\"course-example\">wir arbeiten</div><div class=\"course-example\">mi arbeit</div><div class=\"course-example\">sie arbeiten</div></div> <h5 class=\"lesson2-subtitle\">rechnen</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">ich rechne</div><div class=\"course-example\">du rechnest</div><div class=\"course-example\">er rechnet</div><div class=\"course-example\">sie rechnet</div><div class=\"course-example\">nosotros rechnen</div><div class=\"course-example\">ihr rechnet</div><div class=\"course-example\">sie rechnen</div></div> <h5 class=\"lesson2-subtitle\">usted</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">ich tue</div><div class=\"course-example\">du tust</div><div class=\"course-example\">er tut</div><div class=\"course-example\">sie tut</div><div class=\"course-example\">wir tun</div><div class=\"course-example\">ihr tut</div><div class=\"course-example\">sie tun</div></div> </section> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>2</span>Palabra en cuestión</h4> <div class=\"lesson1-grammar-note\">En oraciones interrogativas que comienzan con la palabra interrogativa, por ejemplo: ¿qué? ¿qué? ¿OMS? ¿por qué? ¿por qué? etc., el verbo está inmediatamente después de la palabra interrogativa.</div> <div class=\"lesson1-card-grid\"><div class=\"course-example\">¿Fue tust du? - ¿Qué estás haciendo?</div><div class=\"kurss-example\">¿Estaba tut er? — ¿Qué está haciendo?</div><div class=\"kurss-example\">¿Era tut sie? — ¿Qué está haciendo?</div><div class=\"kurss-example\">¿Estaba tun sie? — ¿Qué están haciendo?</div></div> </section> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>3</span>Negación con nicht</h4> <div class=\"lesson1-grammar-note\">Si la negación nicht se refiere a un verbo, entonces la palabra negada viene después del verbo.</div> <div class=\"lesson1-card-grid\"><div class=\"course-example\">Er kommt nicht. — No viene.</div><div class=\"kurss-example\">Sie singen nicht. — No cantan.</div></div> </section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-training-wrap\"> <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de traducción de la lección 2\"> <span class=\"lesson1-training-progress\">Conferencia 2 · Traducido: 1 / 15</span> <span class=\"lesson1-training-text\">¿Quién pregunta?</span> </button> <p class=\"lesson1-training-hint\">Haz clic en la card para ver el alemán traducción. Después de la respuesta, el siguiente clic muestra la siguiente card.</p> </div> </div> </details>",
  "kurssLesson6": "<h3>Lección 6</h3> <p class=\"kurss-lesson-intro\">Números, plurales, diéresis y formas plurales de sustantivos.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Aquí está un espacio libre.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, dos Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Todos los Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setts sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zechten einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind doswei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind dos, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind dos, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Cajero.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">¿Cómo sind die Dinge?</div><div class=\"kurss-example\">El martillo es pequeño. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">lieg - es, es, mentiras</div><div class=\"kurss-example\">der Bleistift (bleištift) - lápiz</div><div class=\"kurss-example\">einige (einige) - some</div><div class=\"kurss-example\">hinlegen - poner abajo</div><div class=\"kurss-example\">legt hin - dejar</div><div class=\"kurss-example\">wieder - otra vez</div><div class=\"kurss-example\">aufmachen - desatar</div><div class=\"kurss-example\">er macht auf - desata</div><div class=\"kurss-example\">anspitzen (anšpicen) - escupir</div><div class=\"kurss-example\">er spitzt an - escupe</div><div class=\"kurss-example\">sich setzen - sentarse</div><div class=\"kurss-example\">setzt sich - se sienta</div><div class=\"kurss-example\">der Schlüssel (schlüsel) - llave</div><div class=\"kurss-example\">das Fenster (fenster) - ventana</div><div class=\"kurss-example\">die Tafel (dī tāfel) - pizarra</div><div class=\"kurss-example\">der Garten - jardín</div><div class=\"kurss-example\">der Löffel - cuchara</div><div class=\"kurss-example\">zählen (cēlen) - contar</div><div class=\"kurss-example\">die Nadel - aguja</div><div class=\"kurss-example\">was ist das - ¿Qué es?</div><div class=\"kurss-example\">der Hammer - mazo</div><div class=\"kurss-example\">die Hämmer - mazo</div><div class=\"kurss-example\">der Deckel (dēr dekel) - tapa</div><div class=\"kurss-example\">der Teller - plato</div><div class=\"kurss-example\">der Wagen - carro</div><div class=\"kurss-example\">der Schlitten - trineo, trineo</div><div class=\"kurss-example\">das Ding - cosa</div><div class=\"kurss-example\">die Dinge - cosas</div><div class=\"kurss-example\">¿Cómo sind die Dinge? - ¿Cuáles son las cosas?</div><div class=\"kurss-example\">voll (fōl) - full</div><div class=\"kurss-example\">leer - vacío</div><div class=\"kurss-example\">schwer (schwer) - pesado, difícil</div><div class=\"kurss-example\">leicht - ligero</div><div class=\"kurss-example\">der Eimer - cubo</div><div class=\"kurss-example\">wieviel (wiefiel) - cuántos</div><div class=\"kurss-example\">wieviel Nadeln - cuántos agujas</div><div class=\"kurss-example\">hier (hīr) - aquí</div><div class=\"kurss-example\">dort - allá</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä es el sobretono del vocal a y se pronuncia como e corta o larga estrecha.</div><div class=\"kurss-example\">Ejemplos: das Mädchen (mētchen), die Bänke (dī benke), der Vater (dēr fäter), die Väter (dī fēter).</div><div class=\"kurss-example\">ü es vocal u armónica. Al pronunciarla, los labios deben estar muy redondeados y tratar de pronunciar i con labios redondos.</div><div class=\"course-example\">Ejemplos: fünf, der Schlüssel (schlüsel).</div><div class=\"course-example\">pronunciar ö con labios redondeados, tratando de pronunciar e: der Löffel.</div><div class=\"course-example\">Una vocal doble representa una vocal larga: leer.</div><div class=\"curso-ejemplo\">A doubled eu se pronuncia como oi: neun (noin).</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramática y explicaciones</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">El prefijo acentuado de un verbo compuesto se separa del verbo en tiempo presente y se sitúa al final de la oración.</div><div class=\"kurss-example\">Ejemplos: hinlegen — er legt hin; aufmachen—er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">La palabra numérica uno está en los tres en rondas, si se usa con un sustantivo: en la ronda masculina ein, en la ronda femenina eine, en la ronda media ein.</div><div class=\"kurss-example\">Ejemplos: ein Schüler - un estudiante; eine Schülerin - una estudiante; ein Kind - un niño.</div><div class=\"kurss-example\">Números: eins, zwei, drei, vier (fīr), fünf, sechs (zeks), sieben (zīben), acht, neun (noin), zehn (cēn).</div><div class=\"kurss-example\">Satiana en alemán tiene una forma singular y plural: der Schüler ist pequeño; die Schüler sind klein.</div><div class=\"kurss-example\">El pronombre demostrativo cambia en número y orden en español, pero en alemán usa una forma: das.</div><div class=\"kurss-example\">Ejemplos: es un mazo — das ist ein Hammer; es una aguja: das ist eine Nadel; son martillos—das sind Hämmer; son agujas - das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen - un carro y der Schlitten - un trineo El español tiene plurales, pero en alemán estas palabras se usan en singular y plural.</div><div class=\"kurss-example\">Los sustantivos masculinos y neutros con la terminación -er, -el, -en a menudo no llevan la terminación en plural.</div><div class=\"kurss-example\">Ejemplos: der Hammer — die Hämmer; der Garten—die Gärten; das Fenster—die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Sustantivos femeninos terminados en -el, -er plural toma -n.</div><div class=\"kurss-example\">Ejemplos: die Nadel — die Nadeln; morir Feder - morir Federn.</div><div class=\"kurss-example\">Excepciones: die Mutter (madre) — die Mütter (madres); die Tochter (hija) — die Töchter (hijas).</div><div class=\"kurss-example\">El article indefinido no tiene plural: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">En una oración narrativa, el verbo predicado ocupa el segundo lugar: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lección 6 card de traducción\"><span class=\"lesson1-training-progress\">Lección 6 · Traducir: 1 / 21</span><span class=\"lesson1-training-text\">Paul toma un lápiz y dibuja.</span></button><p class=\"lesson1-training-hint\">Haga clic en las cards para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div> </details>",
  "kurssLesson5": "<h3>Lección 5</h3> <p class=\"kurss-lesson-intro\">Wen?, acusativo, sitzen, fragen y terminación -in.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div> <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div> <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div> <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div> <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div> <div class=\"kurss-example\">¿Es der Schüler klein oder groß? Er ist klein.</div> <div class=\"kurss-example\">Wen fragt ¿Muere Lehrerin? Die Lehrerin fragt die Schülerin.</div> <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div> <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div> <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div> <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div> <div class=\"kurss-example\">Die Mutter liebt das Kind. El lanzamiento de Vater das Kind.</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">sitzen (zicen) - sentarse</div> <div class=\"kurss-example\">fragen (frägen) - preguntar</div> <div class=\"kurss-example\">der Lehrer - profesor</div> <div class=\"kurss-example\">gut - bueno</div> <div class=\"kurss-example\">wen - qué</div> <div class=\"kurss-example\">loben - elogio</div> <div class=\"kurss-example\">der Schüler (schüler) - estudiante</div> <div class=\"kurss-example\">klein - pequeño</div> <div class=\"kurss-example\">groß (grōs) - grande</div> <div class=\"kurss-example\">die Lehrerin - maestra</div> <div class=\"kurss-example\">die Schülerin - colegiala</div> <div class=\"kurss-example\">schlecht (šleht) - malo</div> <div class=\"kurss-example\">tadeln - pelt</div> <div class=\"kurss-example\">oder (ōder) - or</div> <div class=\"kurss-example\">das Kind (kint) - niño</div> <div class=\"kurss-example\">artig (artich) - educado</div> <div class=\"kurss-example\">die Mutter - madre</div> <div class=\"kurss-example\">lieben (līben) - amar</div> <div class=\"kurss-example\">der Vater (fäter) - padre</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">tz es una z duplicada sonido y se pronuncia como z: sitzen (zicen).</div> <div class=\"kurss-example\">v en palabras alemanas se pronuncia como f: der Vater (fäter).</div> <div class=\"kurss-example\">ß es se llama escet y se pronuncia como la s letona: groß (grōs), weiß (veis).</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativo y acusativo</h4><div class=\"lesson1-grammar-note\">En español, el nominativo responde a la pregunta ¿quién? y el acusativo responde a la pregunta ¿qué?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En alemán, la pregunta nominativa es wer? personas y que? sujetos.</div><div class=\"kurss-example\">La pregunta acusativa es wen? personas y que? temas.</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Cambiar artículos al acusativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativo: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Acusativo: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativo: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Acusativ: den Federhalter, die Feder, das Messer.</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">nos sentamos</div><div class=\"kurss-example\">mi asiento</div><div class=\"course-example\">sie sitzen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + acusativo</h4><div class=\"lesson1-grammar-note\">El verbo fragen en alemán requiere un acusativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">finalización -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Muchos sustantivos femeninos se derivan con la terminación -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Lugar del verbo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En una narración oración, el verbo ocupa la segunda posición.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitt.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitt.</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de traducción de la Lección 5\"><span class=\"lesson1-training-progress\">Lección 5 · Traducir: 1 / 16</span><span class=\"lesson1-training-text\">¿Qué ama el padre?</span></button><p class=\"lesson1-training-hint\">Haga clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div> </details>",
  "kurssLesson4": "<h3>Lección 4</h3> <p class=\"kurss-lesson-intro\">Acusativo, nehmen, hinlegen, hinausgehen y adjetivos.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga respondió: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Is der Federhalter weiß? No, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga respondió: „Die Feder ist spitz.“</div><div class=\"kurss-example\">¿Es el Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">¿Fue legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">¿Es das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-número-verde\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">nehmen (nēmen) - tomar</div><div class=\"course-example\">er nimmt (nimt) — toma</div><div class=\"kurss-example\">der Federhalter (dēr fēderhalter) — emplumado</div><div class=\"kurss-example\">einen Federhalter - emplumado</div><div class=\"kurss-example\">zeigen - show</div><div class=\"kurss-example\">schwarz (schwarc) - negro</div><div class=\"kurss-example\">weiß (weis) - blanco</div><div class=\"kurss-example\">die Feder (die fäder) - pluma</div><div class=\"kurss-example\">eine Feder - pluma</div><div class=\"kurss-example\">spitz (špic) - puntiagudo</div><div class=\"kurss-example\">hinlegen - dejar</div><div class=\"kurss-example\">legt hin - dejar</div><div class=\"kurss-example\">das Mädchen (mētchen) - niña</div><div class=\"kurss-example\">das Messer - cuchillo</div><div class=\"kurss-example\">ein Messer - cuchillo</div><div class=\"kurss-example\">scharf - agudo</div><div class=\"kurss-example\">stumpf (štumpf) - contundente</div><div class=\"kurss-example\">dann - luego</div><div class=\"kurss-example\">hinaus - afuera</div><div class=\"kurss-example\">hinausgehen - sal, ve out</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Las terminaciones -en, -er, -el no están acentuadas, por lo que la e en estos extremos es apenas audible: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h en alemán puede ser tanto un sonido como un marcador de longitud para la vocal anterior.</div><div class=\"kurss-example\">Si h es un marcador de longitud, no se pronuncia como un sonido: nehmen (nēmen).</div><div class=\"kurss-example\">Si la vocal va seguida de una sola consonante, la vocal se pronuncia larga: die (dī) Feder (fēder), den (dēn).</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-número-azul\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Acusativo</h4><div class=\"lesson1-grammar-note\">En femenino y neutro, el acusativo es igual al nominativo. Sólo los hombres cambian de ronda.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativo: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Acusativo: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativo: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Acusativo: ein Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"course-example\">ich nehme</div><div class=\"course-example\">du nimmst</div><div class=\"course-example\">er/sie nimmt</div><div class=\"course-example\">wir nehmen</div><div class=\"course-example\">ihr nehmt</div><div class=\"course-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronombres</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er - ronda masculina</div><div class=\"kurss-example\">sie - ronda femenina</div><div class=\"kurss-example\">es - ronda media</div><div class=\"kurss-example\">plural - sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbos separables</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjetivos</h4><div class=\"lesson1-grammar-note\">Si un adjetivo es un adjetivo en una oración, no cambia en orden ni número.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">fit Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negación con nicht</h4><div class=\"lesson1-grammar-note\">Si nicht niega un adjetivo, se coloca delante de la palabra negativa.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Los sustantivos que terminan en -chen y -lein son de orden medio: das Mädchen.</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Conferencia 4 card de traducción\"><span class=\"lesson1-training-progress\">Lección 4 · Traducir: 1 / 16</span><span class=\"lesson1-training-text\">La niña toma un eje de pluma.</span></button><p class=\"lesson1-training-hint\">Haga clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div></details>",
  "kurssLesson3": "<h3>Lección 3</h3> <p class=\"kurss-lesson-intro\">La tercera conferencia: diálogos, palabras, pronunciación, gramática y traducción.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">¿Wer steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">¿Estaba aquí?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">¿Estaba aquí?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">¿Estaba colgado aquí?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort häng eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">¿Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">wer - qué</div><div class=\"course-example\">era - qué</div><div class=\"kurss-example\">hier - aquí</div><div class=\"kurss-example\">dort - allí</div><div class=\"kurss-example\">der Tisch table</div><div class=\"kurss-example\">ein Tisch - mesa</div><div class=\"kurss-example\">die Bank - banco</div><div class=\"kurss-example\">eine Bank - banco</div><div class=\"kurss-example\">liegen - tumbado</div><div class=\"kurss-example\">lieg hier ein Buch? — ¿hay/hay un libro aquí?</div><div class=\"kurss-example\">das Buch — un libro</div><div class=\"kurss-example\">ein Buch — un libro</div><div class=\"kurss-example\">hängen — hang</div><div class=\"kurss-example\">das Bild - imagen</div><div class=\"kurss-example\">ein Bild - imagen</div><div class=\"kurss-example\">die Tafel - pizarra</div><div class=\"kurss-example\">eine Tafel - pizarra</div><div class=\"kurss-example\">wie - alguien, qué</div><div class=\"kurss-example\">es - es</div><div class=\"kurss-example\">polla - grueso, gordo</div><div class=\"kurss-example\">das Heft - cuaderno</div><div class=\"kurss-example\">ein Heft - cuaderno</div><div class=\"kurss-example\">dünn - delgado, delgado</div><div class=\"kurss-example\">niedrig - bajo</div><div class=\"kurss-example\">hoch - alto</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">El sonido ī largo en alemán está representado por ie: liegen (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">ck es doble k: dick (dikk).</div><div class=\"kurss-example\">En palabras de características y circunstancias, la terminación -ig suena como una -ich ligera: niedrig (nīdrich).</div><div class=\"kurss-example\">Si la terminación -ig termina en e: -ige, entonces la g es pronunciado como cierto sonido g: niedrige (nīdrige) Bänke.</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Sujeto de la oración</h4><div class=\"lesson1-grammar-note\">El sujeto de una oración en alemán responde a la pregunta wer? / ¿qué? y nominativo permanente.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">¿Con wer? pregunta por personas.</div><div class=\"kurss-example\">¿Ar qué? pregunta por temas.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">¿Estaba aquí? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artículos</h4><div class=\"lesson1-grammar-note\">En el idioma alemán, el sustantivo tiene 3 casos: masculino, femenino y neutro. Los sustantivos suelen ir precedidos de una palabra llamada article. Esta palabra no está traducida.</div><h5 class=\"lesson2-subtitle\">article definido</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ronda masculina - der</div><div class=\"kurss-example\">ronda femenina - die</div><div class=\"kurss-example\">ronda intermedia - das</div><div class=\"kurss-example\">Plural definido el article para las tres rondas es morir.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">El article indefinido</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">turno masculino — ein</div><div class=\"kurss-example\">ronda femenina - eine</div><div class=\"kurss-example\">ronda intermedia - ein</div><div class=\"kurss-example\">El indefinido el article no tiene plural.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Sustantivos propios</h4><div class=\"lesson1-grammar-note\">Sin artículos delante de nombres propios.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Lugar del verbo</h4><div class=\"lesson1-grammar-note\">En una oración narrativa, el verbo ocupa el segundo lugar.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En alemán, los objetos que están en posición vertical se dicen que están de pie:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Los objetos que están en posición horizontal se dice que están en posición horizontal:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Los objetos también pueden colgar:<br>die Karte colgar<br>el Tafel colgar</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-número-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de traducción de la lección 3\"><span class=\"lesson1-training-progress\">Lección 3 · Traducir: 1 / 22</span><span class=\"lesson1-training-text\">¿Cuentas?</span></button><p class=\"lesson1-training-hint\">Haz clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div></details>",
  "kurssLesson7": "<h3>Lección 7</h3> <p class=\"kurss-lesson-intro\">Séptima lección: expresión de mando, forma de dirección y plural.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">Hans, singe ein Lied! ¿Qué estás haciendo? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! ¿Fue Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans y Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! ¿Fue Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans y Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffent die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffent Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">singen — cantar</div><div class=\"course-example\">singe — cantar</div><div class=\"kurss-example\">singt - cantar</div><div class=\"kurss-example\">singen Sie - cantar</div><div class=\"kurss-example\">das Lied (das lit) - canción</div><div class=\"kurss-example\">Sie - Tú</div><div class=\"kurss-example\">zählen - conde</div><div class=\"kurss-example\">das Fräulein (froilein) - jovencita</div><div class=\"kurss-example\">der Müller - molinero</div><div class=\"kurss-example\">öffnen - abierto</div><div class=\"kurss-example\">das Fenster (fenster) - ventana</div><div class=\"kurss-example\">alle - todos</div><div class=\"kurss-example\">der Spiegel - espejo</div><div class=\"kurss-example\">der Lappen - trapo, fregona</div><div class=\"kurss-example\">der Spaten - pala</div><div class=\"kurss-example\">der Besen - escoba</div><div class=\"kurss-example\">die Schaufel - pala</div><div class=\"kurss-example\">die Schüssel - cuenco</div><div class=\"kurss-example\">das Zimmer - habitación</div><div class=\"kurss-example\">das Ufer (üfer) - orilla</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp al principio de una palabra o sílaba se pronuncia como šp: der Spiegel (para špīgel).</div><div class=\"kurss-example\">sch se pronuncia como letón š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">El diptongo äu se pronuncia como letón oi: das Fräulein (das froilein).</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Expresión de comandos</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La expresión de comando en segunda persona del singular corresponde a para la 2ª persona del singular del verbo sin la terminación personal -st, añadiendo la terminación -e.</div><div class=\"kurss-example\">Ejemplos: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Muy a menudo la terminación -e no se utiliza si la forma del comando se vuelve monosilábica: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Comando plural</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La forma del comando en la segunda persona del plural es similar a la segunda persona del presente plural, pero se usa sin pronombre.</div><div class=\"kurss-example\">Ejemplos: antortet!, arbeitt!, öffnett!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Forma de tratamiento con Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La forma de tratamiento con \"Usted\" se parece a la tercera persona del plural. El pronombre Sie es escrito con mayúscula y después del verbo.</div><div class=\"kurss-example\">Ejemplos: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Para una pronunciación más fácil del verbo öffnen en la 2.ª y 3.ª persona del singular y en la segunda persona del plural, e se inserta entre la raíz y la terminación: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Ejercicio</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de ejercicios de la lección 7\"><span class=\"lesson1-training-progress\">Lección 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen - preguntar</span></button><p class=\"lesson1-training-hint\">Toque la card para ver los formularios de comando.</p></div></div></details>",
  "kurssLesson1": "<h3>Lección 1</h3> <p class=\"kurss-lesson-intro\">Primera lección: verbos en presente, sustantivos, pronunciación, gramática y traducción.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbos en presente</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-info\">Verbos y sus conjugaciones en tiempo presente.</div> <div class=\"lesson1-verb-cards\"> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — venir</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>yo vengo</span><span>du</span><strong>kommst</strong><span>tú vienes</span><span>er / sie</span><strong>kommt</strong><span>él / ella viene</span><span>wir</span><strong>kommen</strong><span>nosotros ven</span><span>ihr</span><strong>kommt</strong><span>tú vienes</span><span>sie / Sie</span><strong>kommen</strong><span>ellos / tú vienes</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>gehen - go</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>yo voy</span><span>du</span><strong>gehst</strong><span>tú vas</span><span>er / sie</span><strong>geht</strong><span>he / ella va</span><span>wir</span><strong>gehen</strong><span>nosotros vamos</span><span>ihr</span><strong>geht</strong><span>tú ejat</span><span>sie / Sie</span><strong>gehen</strong><span>ellos / tú vas</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>stehen - pararse</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>I stand</span><span>du</span><strong>stehst</strong><span>tú estás de pie</span><span>er / sie</span><strong>steht</strong><span>él / ella está de pie</span><span>wir</span><strong>stehen</strong><span>nosotros estamos de pie</span><span>ihr</span><strong>steht</strong><span>tú estás de pie</span><span>sie / Sie</span><strong>stehen</strong><span>ellos / Tú estás</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>singen - to canta</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>yo canto</span><span>du</span><strong>singst</strong><span>tú cantas</span><span>er / sie</span><strong>singt</strong><span>él / ella canta</span><span>wir</span><strong>singen</strong><span>nosotros cantamos</span><span>ihr</span><strong>singt</strong><span>tú cantas</span><span>sie / Sie</span><strong>singen</strong><span>ellos / tú cantas</span></div> </article> </div> <section class=\"lesson1-block\"> <h4>Ejemplos</h4> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Martha?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und sing?<br>Albert y Martha kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Martha stehen und singen.</div></div> </section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>El La pronunciación aproximada de las palabras se da entre paréntesis con letras letonas.<br>Esto también debería seguirse en futuras conferencias.</span></div> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vir) - we</div><div class=\"kurss-example\">En la palabra \"wir\" la letra i se pronuncia larga.</div><div class=\"kurss-example\">kommen (komen) - venir</div><div class=\"kurss-example\">gehen (gē-en) - ir</div><div class=\"kurss-example\">stehen (šte-en) - stand</div><div class=\"kurss-example\">singen (zingen) - canta</div><div class=\"kurss-example\">du (dū) kommst - tú vienes</div><div class=\"kurss-example\">er (er) kommt - él viene</div><div class=\"kurss-example\">sie (zī) kommt - ella viene</div><div class=\"kurss-example\">wer (vēr) - ¿qué?</div><div class=\"kurss-example\">ja (sí) - sí</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number\" lesson1-número-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La pronunciación correcta de las palabras, marcadas con letras letonas, se proporciona en las conferencias.</div><div class=\"kurss-example\">Wir (marido) - nosotros La palabra wir siempre se pronuncia larga.</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitivo</h4><div class=\"lesson1-grammar-note\">La forma base de un verbo. Normalmente el infinitivo termina en -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Presente terminaciones</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Eliminar <span class=\"lesson1-ending-accent\">-en</span> de las formas base del verbo y agrega la terminación.</strong></p><p>Ejemplo: kommen → komm + terminación</p><div class=\"lesson1-ending-process\" aria-label=\"El proceso de formar la terminación presente\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>forma base</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>eliminar <span class=\"lesson1-ending-accent\">-es</span></strong><span>la raíz permanece</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>raíz</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>end</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"course-example\">ich → -e</div><div class=\"course-example\">du → -st</div><div class=\"course-example\">er / sie → -t</div><div class=\"course-example\">wir → -en</div><div class=\"course-example\">ihr → -t</div><div class=\"course-example\">sie → -en</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Ejemplos</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Oraciones de preguntas</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>En una oración de preguntas en alemán, el verbo generalmente se mueve a la primera posición.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En letón:<br>Vienes.<br>¿Vienes?</div><div class=\"kurss-example\">Alemán en:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst - vienes<br>kommst du? - ¿Vienes?</div><div class=\"kurss-example\">er canta - canta<br>singt er? — ¿canta?</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Diferencia de persona</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt - él viene</div><div class=\"kurss-example\">sie kommt - ella viene</div><div class=\"kurss-example\">sie kommen - ellos / ella viene</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-training-wrap\"> <button class=\"lesson1-training-flashcard\" tipo=\"botón\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de entrenamiento de la Lección 1\"> <span class=\"lesson1-training-progress\">Lección 1 · Traducido: 1 / 11</span> <span class=\"lesson1-training-text\">¿Vienes?</span> </button> <p class=\"lesson1-training-hint\">Haz clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p> </div> </div> </details>"
};

